* {
  box-sizing: border-box;
}

.map {
  font-family: Arial, sans-serif;
  color: #111827;
  background: #ffffff;
  padding: 16px;
  width: 100%;
  min-height: 360px;
}

.debug {
  background: #fffbeb;
  border: 1px solid #f59e0b;
  color: #92400e;
  padding: 8px 10px;
  font-size: 12px;
  margin-bottom: 12px;
}

.map-header {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
  margin-bottom: 16px;
}

h2 {
  margin: 0;
  font-size: 20px;
}

p {
  margin: 5px 0 0;
  color: #667085;
  font-size: 12px;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  font-size: 11px;
  color: #344054;
  justify-content: flex-end;
}

.legend span {
  display: flex;
  align-items: center;
  gap: 5px;
}

.legend i {
  width: 10px;
  height: 10px;
  display: inline-block;
  border: 1px solid rgba(0, 0, 0, 0.08);
}

.empty {
  background: #e5e7eb;
}

.assigned {
  background: #0f766e;
}

.full {
  background: #b42318;
}

.receiving {
  background: #2563eb;
}

.shipping {
  background: #9333ea;
}

.inactive {
  background: #98a2b3;
}

.empty-state {
  display: none;
  border: 1px dashed #cbd5e1;
  background: #f8fafc;
  padding: 18px;
  color: #667085;
  font-size: 13px;
  text-align: center;
  margin-bottom: 12px;
}

.zones {
  display: grid;
  gap: 16px;
}

.zone {
  border: 1px solid #d9e0e7;
  background: #f8fafc;
}

.zone-title {
  padding: 10px 12px;
  background: #111827;
  color: white;
  font-weight: 700;
  font-size: 13px;
}

.racks {
  display: grid;
  gap: 12px;
  padding: 12px;
}

.rack {
  border: 1px solid #d9e0e7;
  background: white;
}

.rack-title {
  padding: 8px 10px;
  border-bottom: 1px solid #d9e0e7;
  font-size: 12px;
  font-weight: 700;
  color: #344054;
  background: #ffffff;
}

.bins {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(132px, 1fr));
  gap: 8px;
  padding: 10px;
}

.bin {
  border: 1px solid #d9e0e7;
  background: #e5e7eb;
  min-height: 78px;
  padding: 8px;
  cursor: pointer;
  transition: outline 0.1s ease, transform 0.1s ease;
}

.bin:hover {
  outline: 2px solid #111827;
  transform: translateY(-1px);
}

.bin.selected {
  outline: 3px solid #111827;
}

.bin.assigned {
  background: #ecfdf5;
  border-color: #5eead4;
}

.bin.full {
  background: #fff1f3;
  border-color: #fda29b;
}

.bin.receiving {
  background: #eff6ff;
  border-color: #93c5fd;
}

.bin.shipping {
  background: #faf5ff;
  border-color: #d8b4fe;
}

.bin.inactive {
  opacity: 0.45;
  background: #f2f4f7;
}

.bin-code {
  font-size: 13px;
  font-weight: 800;
  overflow-wrap: anywhere;
}

.bin-name {
  color: #667085;
  font-size: 11px;
  margin-top: 3px;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.bin-meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin-top: 8px;
  font-size: 11px;
  color: #344054;
}

.selected-panel {
  margin-top: 14px;
  border: 1px solid #d9e0e7;
  padding: 10px 12px;
  background: #ffffff;
}

.selected-panel span {
  display: block;
  color: #667085;
  font-size: 11px;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.selected-panel b {
  font-size: 13px;
}

